BEGIN;

-- Batch editorial público reproducible. Sólo Entity y su traducción es.
-- No modifica entidades canónicas, relaciones, assertions, sources ni citations.

UPDATE "Entity" SET
  summary = 'Pablo Picasso (Málaga, 1881–Mougins, 1973) fue un artista formado en la academia que desarrolló en París un lenguaje decisivo para la modernidad artística. Su trayectoria atraviesa la ruptura con la representación tradicional y alcanza una dimensión política visible en el encargo de Guernica para el pabellón español de 1937.',
  content = 'Pablo Picasso nació en Málaga en 1881, recibió una formación académica en Bellas Artes y vivió en Barcelona durante los años del cambio de siglo. Se instaló en París en 1904, donde su trabajo empezó a ser reconocido por su ruptura con los sistemas de representación tradicionales.\n\nSu práctica también revisó asuntos de la mitología clásica y obras de la tradición artística, al tiempo que incorporó estímulos no naturalistas como las máscaras africanas. En 1937 recibió el encargo de realizar una gran pintura para el pabellón español de la Exposición Internacional de París; ese contexto dio lugar a una de las obras centrales de su trayectoria, Guernica.'
WHERE id='cmsvvxi9700hc85sjjoidcq8a';

UPDATE "Entity" SET
  summary = 'El cubismo fue uno de los estilos más influyentes del siglo XX. Surgido alrededor de 1907 en torno a Picasso, Braque y la revisión de la representación visual, abrió posibilidades que alimentarían varios lenguajes abstractos posteriores.',
  content = 'Se considera generalmente que el cubismo comenzó alrededor de 1907, cuando Les Demoiselles d’Avignon ya incorporaba elementos cubistas. El nombre parece proceder de un comentario de Louis Vauxcelles sobre unas pinturas de Georges Braque expuestas en París en 1908, descritas por el crítico como formas reducidas a contornos geométricos y cubos.\n\nMás que un estilo aislado, el cubismo transformó la manera de tratar la realidad visual. Tate lo considera un punto de partida para estilos abstractos posteriores, entre ellos el constructivismo y el neoplasticismo.'
WHERE id='cmsvvxhgm002r85sjdntcbn33';

UPDATE "Entity" SET
  summary = 'Pintado por Sandro Botticelli hacia 1484–1486, El nacimiento de Venus representa a la diosa del amor y la belleza llegando a la isla de Chipre, impulsada por el viento. La obra destaca por el uso temprano y ambicioso del temple sobre lienzo en una composición destinada a una colección noble.',
  content = 'El nacimiento de Venus fue pintado hacia 1484–1486 con temple sobre lienzo y mide 172,5 × 278,5 cm. Se conserva en la Galería Uffizi de Florencia. Aunque se conoce como El nacimiento de Venus, la composición muestra a Venus llegando a tierra, en la isla de Chipre, nacida de la espuma del mar y llevada por los vientos Céfiro y quizá Aura.\n\nEl soporte es significativo: el lienzo se utilizaba ampliamente en el siglo XV para obras decorativas destinadas a casas nobles. La elección permite leer la obra dentro de las prácticas materiales y culturales de la pintura florentina de su tiempo.'
WHERE id='cmsvvxif800ku85sjmrawpu0e';

UPDATE "Entity" SET
  summary = 'Maman es una escultura monumental de Louise Bourgeois que reúne maternidad, cuidado y amenaza en la figura de una araña de escala arquitectónica. Su bronce, acero inoxidable y mármol convierten el cuerpo escultórico en una experiencia espacial.',
  content = 'Realizada en 1999, Maman mide aproximadamente 927 × 891 × 1024 cm y está vinculada en la base de datos a la colección del Guggenheim Bilbao. La obra emplea bronce, acero inoxidable y mármol, materiales que hacen visible la tensión entre peso, fragilidad y protección.\n\nLa araña funciona como una presencia que ocupa el espacio y obliga al espectador a situarse bajo ella. Las relaciones publicadas la vinculan con maternidad, cuidado, monumento, ensamblaje y materialidad; esas conexiones permiten reconocer que su escala no es un efecto decorativo, sino parte de su sentido escultórico.'
WHERE id='cmqmnymtz004o4vsj0wtos3ox';

UPDATE "Entity" SET
  summary = 'Las Meninas, pintada por Diego Velázquez en 1656, es un óleo sobre lienzo que organiza una compleja escena de corte alrededor de la mirada, la representación y la posición del espectador. Conservada en el Museo del Prado, la obra mide 318 × 276 cm.',
  content = 'Velázquez pintó Las Meninas en 1656 con óleo sobre lienzo. La obra se conserva en el Museo del Prado de Madrid y forma parte de las relaciones publicadas con el Barroco, el retrato, la mirada, la representación y la perspectiva lineal.\n\nSu interés no depende sólo de quién aparece en la escena, sino de cómo la pintura distribuye las posiciones de quienes miran, son mirados y parecen participar en la producción de la imagen. El espacio cortesano se convierte así en un problema visual: la pintura muestra una escena y, al mismo tiempo, hace visible el acto de representar.'
WHERE id='cmqmnymu5004r4vsjrvya8fdp';

UPDATE "Entity" SET
  summary = 'Saturno devorando a su hijo pertenece a las Pinturas negras que Francisco de Goya realizó entre 1820 y 1823. Su cuerpo deformado, su violencia y su oscuridad convierten el mito en una imagen extrema del tiempo, la destrucción y el miedo.',
  content = 'La obra fue realizada entre 1820 y 1823 con óleo trasladado a lienzo y mide 143,5 × 81,4 cm. Se conserva en el Museo del Prado de Madrid, dentro del conjunto de las Pinturas negras.\n\nLa escena del dios que devora a su hijo no aparece tratada como una narración distante. La escala, la materia pictórica y la expresión de Saturno concentran la violencia en el cuerpo y la convierten en una experiencia visual inmediata. Por eso la obra se relaciona de forma especialmente fértil con violencia, tiempo y dolor.'
WHERE id='cmqmnymt100494vsjefqf57vp';

UPDATE "Entity" SET
  summary = 'Marcel Duchamp (1887–1968) fue un artista franco-estadounidense cuya práctica desplazó la atención desde la fabricación del objeto hacia la elección, la idea y el marco que decide qué puede considerarse arte. Su trabajo atraviesa la pintura, el objeto y la experimentación conceptual.',
  content = 'Duchamp nació en Blainville-Crevon en 1887 y murió en 1968. Se le sitúa entre Francia y Estados Unidos y se le identifica con el objeto, la pintura y la práctica conceptual.\n\nSu trayectoria se articula alrededor de la autoría, el objeto, el juego y la definición de arte. Obras como Fountain y Bottle Rack permiten seguir cómo una elección y un desplazamiento de contexto pueden convertirse en el centro de la experiencia artística.'
WHERE id='cmqmnymsu00474vsjen0o2yni';

UPDATE "Entity" SET
  summary = 'Nighthawks, pintada por Edward Hopper en 1942, reúne una escena nocturna, luz artificial y figuras aisladas en un interior urbano. El óleo sobre lienzo se conserva en el Art Institute of Chicago y mide 84,1 × 152,4 cm.',
  content = 'Edward Hopper pintó Nighthawks en 1942 con óleo sobre lienzo. La obra se conserva en el Art Institute of Chicago y está relacionada con la ciudad y con el realismo.\n\nLa composición concentra la atención en un local iluminado durante la noche, separado de la calle por el cristal. La arquitectura, la distancia entre las figuras y la ausencia de un relato cerrado hacen que la espera y el aislamiento formen parte de la imagen tanto como sus personajes.'
WHERE id='cmqmnymui004v4vsjjq7adr8c';

UPDATE "Entity" SET
  summary = 'Edward Hopper (1882–1967) fue un pintor estadounidense que convirtió escenas urbanas, arquitectura, luz y momentos de espera en imágenes duraderas de la vida moderna. Su obra se asocia con la ciudad, la soledad y la experiencia cotidiana.',
  content = 'Hopper nació en Nyack en 1882 y murió en 1967. Fue un pintor y grabador estadounidense.\n\nSu relación con la ciudad y con obras como Nighthawks permite reconocer una preocupación persistente por los espacios cotidianos y por la distancia que puede aparecer incluso cuando varias personas comparten un mismo lugar. La luz y la arquitectura no son un fondo neutro: organizan la experiencia de los personajes.'
WHERE id='cmqmnymsm00454vsjw8djfbo0';

UPDATE "Entity" SET
  summary = 'Francis Bacon (1909–1992) desarrolló una pintura centrada en la vulnerabilidad del cuerpo, la deformación y la intensidad psicológica. Su obra convierte la figura humana en un lugar de tensión entre presencia, violencia y encierro.',
  content = 'Francis Bacon nació en Dublín en 1909 y murió en 1992. Se le sitúa entre Irlanda y el Reino Unido y se le identifica principalmente con la pintura.\n\nEn su trabajo, el cuerpo no aparece como una forma estable o idealizada. La deformación, la carne y el espacio cerrado producen una imagen sometida a fuerzas psicológicas difíciles de resolver. Esa tensión explica su relación con obras y asuntos donde se cruzan poder, violencia, miedo y representación.'
WHERE id='cmqmnymsr00464vsj35ef244h';

UPDATE "Entity" SET
  summary = 'Fountain es un ready-made de Marcel Duchamp fechado en 1917. Al presentar un objeto de porcelana como obra, desplaza la atención hacia la elección, la autoría y el papel de la institución que reconoce algo como arte.',
  content = 'Fountain está fechada en 1917 y se identifica como un ready-made de porcelana. La pieza original no se conserva como un objeto único en la información disponible: las relaciones de procedencia señalan réplicas en colecciones museísticas.\n\nSu interés está en el cambio de marco. El gesto no consiste en modelar una forma nueva, sino en seleccionar un objeto y situarlo ante el sistema del arte. Por eso la obra permite seguir, de manera concreta, la relación entre objeto, autoría y definición institucional.'
WHERE id='cmqmnymuo004x4vsjni2c67mr';

UPDATE "Entity" SET
  summary = 'Bottle Rack es un ready-made metálico de Marcel Duchamp, fechado en 1914. La obra convierte un objeto funcional en una pregunta sobre elección, uso y valor artístico.',
  content = 'Bottle Rack está fechada en 1914 y se registra como un ready-made de metal; la información disponible indica que existen réplicas en museo. Su operación es sencilla pero decisiva: separar un objeto de la función para la que fue fabricado y presentarlo dentro de un contexto artístico.\n\nLa obra permite comprender por qué Duchamp resulta central para las discusiones sobre autoría y objeto. El sentido no procede de una destreza artesanal visible, sino de la decisión que reorganiza la atención del espectador.'
WHERE id='cmqmnymuu004z4vsjje52odxv';

UPDATE "Entity" SET
  summary = 'Guernica, pintado por Pablo Picasso en 1937, es un óleo sobre lienzo de gran formato vinculado a la Guerra Civil española. Su escala y sus figuras fragmentadas convierten la violencia y la memoria en una experiencia pública.',
  content = 'Guernica fue pintado en 1937 con óleo sobre lienzo y mide 349,3 × 776,6 cm. Se conserva en el Museo Nacional Centro de Arte Reina Sofía de Madrid. Las relaciones publicadas lo vinculan con Pablo Picasso, la Guerra Civil española, la guerra, la violencia, el exilio, la memoria, la propaganda y la pintura de historia.\n\nLa obra no describe una escena bélica mediante un relato lineal. Su composición reúne cuerpos quebrados, animales, gritos y signos que hacen de la destrucción una imagen colectiva. El gran formato refuerza esa dimensión pública: el cuadro no funciona sólo como episodio, sino como memoria visual de la violencia.'
WHERE id='cmsvvxiio00mv85sj920czcuo';

UPDATE "Entity" SET
  summary = 'Judith Baca es pintora, muralista y académica; trabaja de forma colaborativa con comunidades para crear lugares de memoria pública. Sus iniciativas atienden especialmente a poblaciones históricamente marginadas y convierten el mural en una práctica social.',
  content = 'Judith Baca trabaja con comunidades para crear sitios de memoria pública. El testimonio conservado del Smithsonian American Art Museum relaciona esa práctica con mujeres, trabajadores pobres, jóvenes, personas mayores, comunidades LGBTQ+ y comunidades inmigrantes.\n\nSu trabajo muestra que un mural puede ser simultáneamente una imagen, un proceso colectivo y un lugar donde una comunidad hace visible su propia historia. La dimensión pública no es un añadido a la obra: forma parte de su método y de su significado.'
WHERE id='cmtptpmi90002gxss42zn1ydw';

UPDATE "Entity" SET
  summary = 'Josef Albers (1888–1976) fue un artista y profesor cuya enseñanza en Black Mountain College estuvo marcada por el aprendizaje práctico y por los principios que había llevado desde la Bauhaus. Su actividad conectó experimentación artística, pedagogía y vida colectiva.',
  content = 'Josef Albers estuvo en Black Mountain College desde 1933 hasta 1949 y fue contratado como su primer profesor de arte. Las fuentes conservadas describen una enseñanza basada en la práctica antes que en la teoría, el aprendizaje haciendo y la idea de que el arte forma parte de una educación general.\n\nLa relación con la Bauhaus es importante porque muestra cómo esos principios pedagógicos se trasladaron a otro contexto. En Black Mountain College, estudiar arte no significaba aislarlo de la vida intelectual: implicaba revisar las jerarquías entre disciplinas y entender la experiencia como parte del aprendizaje.'
WHERE id='cmsvvxj8a012s85sjedihcwi5';

UPDATE "Entity" SET
  summary = 'Black Mountain College fue una institución educativa cuya historia estuvo ligada a la experimentación artística, la vida comunitaria y la llegada de artistas e intelectuales desplazados por el fascismo europeo. Sus prácticas combinaban estudio, trabajo colectivo y actividades culturales.',
  content = 'Las fuentes del Black Mountain College Museum + Arts Center describen una comunidad en la que profesores y estudiantes preparaban disfraces y decoraciones para fiestas temáticas, incluidas celebraciones vinculadas al dadaísmo y a la Antigüedad griega. Otra exposición digital relaciona la historia del college con el exilio provocado por el ascenso del fascismo en Europa.\n\nLa institución importa como espacio de intercambio entre educación, arte y vida colectiva. La presencia de Josef Albers y la recepción de principios de la Bauhaus muestran cómo la enseñanza podía organizarse alrededor de la práctica, la colaboración y la experiencia.'
WHERE id='cmsvvxiy500w485sjaswn4h4o';

UPDATE "Entity" SET
  summary = 'La gran ola de Kanagawa es una xilografía de Katsushika Hokusai, fechada hacia 1831, realizada con tinta y color sobre papel. La obra se sitúa en relación con el ukiyo-e y convierte el paisaje y la fuerza del mar en una imagen de gran tensión formal.',
  content = 'La obra está fechada hacia 1831 y mide 25,7 × 37,9 cm. Se registra como una xilografía en color, realizada con tinta y color sobre papel, y se conserva en The Metropolitan Museum of Art de Nueva York. Las relaciones publicadas la vinculan con Hokusai, el ukiyo-e, el paisaje, la naturaleza, el papel y la xilografía.\n\nLa forma de la ola organiza la imagen como una fuerza que domina el campo visual. La obra permite reconocer cómo una técnica de reproducción múltiple puede construir una escena de enorme precisión, ritmo y tensión entre la naturaleza y la presencia humana.'
WHERE id='cmsvvxile00og85sjyt9ud6rp';

UPDATE "Entity" SET
  summary = 'El busto de Nefertiti es una escultura de piedra caliza y estuco, de 47 cm de altura, vinculada en el grafo con el arte egipcio, el retrato y la tradición. Su interés está en la concentración de identidad, representación y materialidad en una imagen de escala humana.',
  content = 'El busto es una obra de piedra caliza y estuco de 47 cm de altura. Las relaciones publicadas lo vinculan con el arte egipcio, el retrato, la iconografía, el cuerpo, el pigmento, el oro y la tradición, además de señalar asociaciones institucionales con el Museo Británico y el Museo Egipcio de El Cairo.\n\nSu escala permite una relación cercana con el rostro representado, mientras que los materiales recuerdan que la imagen no es sólo apariencia: también es superficie, color y trabajo escultórico. El retrato aparece así como una construcción material de identidad.'
WHERE id='cmsvvxidz00k385sjl9wykswf';

UPDATE "Entity" SET
  summary = 'Olympia, pintada por Édouard Manet en 1863, es un óleo sobre lienzo relacionado con el cuerpo, el deseo, el desnudo, la mirada y el género. Su lugar en el realismo se entiende a través de la fricción entre la tradición del desnudo y la presencia directa de la figura.',
  content = 'Olympia fue pintada en 1863 con óleo sobre lienzo y mide 130,5 × 190 cm. La obra se conserva en el Musée d’Orsay de París. Las relaciones publicadas la vinculan con Édouard Manet, el realismo, el desnudo, el cuerpo, el deseo, la sexualidad, el género y la mirada.\n\nEsas conexiones sitúan la obra en un punto de tensión: retoma un formato reconocible de la historia del arte, pero hace que la figura y su mirada interrumpan la distancia idealizada del desnudo tradicional. El espectador queda implicado en una escena donde mirar también significa ocupar una posición social.'
WHERE id='cmsvvxihi00m785sje6zpfn92';

UPDATE "Entity" SET
  summary = 'El 3 de mayo de 1808, pintado por Francisco de Goya en 1814, es un óleo sobre lienzo que representa la violencia de la guerra y la muerte desde la vulnerabilidad de quienes la padecen. Conservado en el Museo del Prado, mide 268 × 347 cm.',
  content = 'Goya pintó El 3 de mayo de 1808 en 1814 con óleo sobre lienzo. La obra mide 268 × 347 cm y se conserva en el Museo del Prado de Madrid. Las relaciones publicadas la vinculan con la Guerra, la Muerte, la Violencia, el Romanticismo, el grabado y Francisco de Goya.\n\nLa luz concentra la escena en las víctimas y en el instante anterior a la ejecución. La pintura no convierte la violencia en una hazaña ordenada: hace visible el miedo, el cuerpo expuesto y la desigualdad entre quienes disparan y quienes esperan. Su fuerza histórica nace de esa elección de punto de vista.'
WHERE id='cmsvvxigt00ls85sj3rcd1lec';

UPDATE "EntityTranslation" et SET
