WHERE et."entityId"=e.id AND et.locale='es' AND e.id IN (
 'cmsvvxi9700hc85sjjoidcq8a','cmsvvxhgm002r85sjdntcbn33','cmsvvxif800ku85sjmrawpu0e',
 'cmqmnymtz004o4vsj0wtos3ox','cmqmnymu5004r4vsjrvya8fdp','cmqmnymt100494vsjefqf57vp',
 'cmqmnymsu00474vsjen0o2yni','cmqmnymui004v4vsjjq7adr8c','cmqmnymsm00454vsjw8djfbo0',
 'cmqmnymsr00464vsj35ef244h','cmqmnymuo004x4vsjni2c67mr','cmqmnymuu004z4vsjje52odxv',
 'cmsvvxio00mv85sj920czcuo','cmtptpmi90002gxss42zn1ydw','cmsvvxj8a012s85sjedihcwi5',
 'cmsvvxiy500w485sjaswn4h4o','cmsvvxile00og85sjyt9ud6rp','cmsvvxidz00k385sjl9wykswf',
